namespace {
int checks=0;
void check(bool value,const char* message){++checks;if(!value){std::cerr<<"FAIL: "<<message<<"\n";std::exit(1);}}
Snapshot fixture(uint32_t tick){Snapshot s;s.tick=tick;s.players[0].entity=1;s.players[0].slot=1;s.players[1].entity=2;s.players[1].slot=2;return s;}
void pump(Session& a,Session& b,int milliseconds=50){auto end=monotonic_milliseconds()+milliseconds;while(monotonic_milliseconds()<end){a.tick(monotonic_milliseconds());b.tick(monotonic_milliseconds());std::this_thread::sleep_for(std::chrono::milliseconds(1));}}
}
